/** Server-only illustrative imagery. Legal facts stay in the Cala-backed UI. */
import { fal } from "@fal-ai/client"

const MODEL = "fal-ai/flux-2"
export const ACTIVITY_VIDEO_MODEL = "fal-ai/fast-svd-lcm/text-to-video"

export async function generateIllustration(prompt: string): Promise<string> {
  const key = process.env.FAL_KEY
  if (!key) throw new Error("FAL_KEY is not set")

  fal.config({ credentials: key })
  const result = await fal.subscribe(MODEL, {
    input: {
      prompt,
      image_size: "landscape_16_9",
      num_images: 1,
      output_format: "webp",
      enable_safety_checker: true,
    },
  })

  const image = (result.data as { images?: Array<{ url?: string }> }).images?.[0]?.url
  if (!image) throw new Error("fal returned no image")
  return image
}

/** A short, silent activity loop. It is illustrative; never encode legal facts in video. */
function configure() {
  const key = process.env.FAL_KEY
  if (!key) throw new Error("FAL_KEY is not set")
  fal.config({ credentials: key })
}

/** Queue a short activity loop without blocking a chat request. */
export async function submitActivityLoop(prompt: string): Promise<string> {
  configure()
  const job = await fal.queue.submit(ACTIVITY_VIDEO_MODEL, {
    input: {
      prompt,
      video_size: "landscape_16_9",
      fps: 10,
      steps: 4,
      motion_bucket_id: 110,
    },
  })
  return job.request_id
}

/** Retrieve the completed clip; callers can poll it separately from the request. */
export async function getActivityLoop(requestId: string): Promise<string | null> {
  configure()
  const status = await fal.queue.status(ACTIVITY_VIDEO_MODEL, { requestId })
  if (status.status !== "COMPLETED") return null
  const result = await fal.queue.result(ACTIVITY_VIDEO_MODEL, { requestId })
  const video = (result.data as { video?: { url?: string } }).video?.url
  if (!video) throw new Error("fal returned no video")
  return video
}
