/** Create the activity loop shown only for lunar extraction questions. */
import { mkdir, readFile, writeFile } from "fs/promises"
import { join } from "path"
import { getActivityLoop, submitActivityLoop } from "../lib/mooneto/fal"

const prompt = `A compact autonomous lunar mining rover slowly excavates a small mound of pale lunar regolith.
The scoop lowers, collects dust, and rises once; fine dust drifts gently in low gravity.
Wide static camera, distant Earth, elegant realistic 3D editorial style, quiet and precise.
No people, no flags, no logos, no text, no labels, no watermark, no explosions.`

async function main() {
  const directory = join(process.cwd(), "public", "illustrations")
  const jobFile = join(directory, ".lunar-mining-loop-job.json")
  await mkdir(directory, { recursive: true })

  let requestId: string
  try {
    requestId = JSON.parse(await readFile(jobFile, "utf8")).requestId
  } catch {
    requestId = await submitActivityLoop(prompt)
    await writeFile(jobFile, JSON.stringify({ requestId }, null, 2))
    console.log(`[fal] queued lunar mining loop: ${requestId}`)
    return
  }

  const url = await getActivityLoop(requestId)
  if (!url) {
    console.log(`[fal] lunar mining loop still processing: ${requestId}`)
    return
  }
  const response = await fetch(url)
  if (!response.ok) throw new Error(`Could not download fal video (${response.status})`)

  const output = join(directory, "lunar-mining-loop.mp4")
  await mkdir(directory, { recursive: true })
  await writeFile(output, Buffer.from(await response.arrayBuffer()))
  console.log(`[fal] wrote ${output}`)
}

main().catch((error) => {
  console.error("[fal]", error)
  process.exitCode = 1
})

