  France: "FR", Germany: "DE", Italy: "IT", Brazil: "BR", "United Arab Emirates": "AE",
  "South Korea": "KR", "Republic of Korea": "KR", Ukraine: "UA", Poland: "PL",
  Mexico: "MX", Israel: "IL", "Saudi Arabia": "SA", Nigeria: "NG", Colombia: "CO",
  Spain: "ES", Argentina: "AR", Netherlands: "NL", Belgium: "BE", Austria: "AT",
}

function flag(name: string) {
  const code = ISO[name]
  if (!code) return "🌍"
  return String.fromCodePoint(...[...code].map((c) => 0x1f1e6 + c.charCodeAt(0) - 65))
}

function depictsMining(answer: Answer | null) {
  return answer ? depictsMiningText(`${answer.question} ${answer.resolved ?? ""}`) : false
}

function depictsMiningText(text: string) {
  return /\b(min(e|ing)|extract(ion|ed|ing)?|resources?)\b/i.test(text)
}

type FieldStar = { left: string; top: string; size: number; delay: number }

function makeStarField(seed: string): FieldStar[] {
  let hash = [...seed].reduce((value, char) => (value * 31 + char.charCodeAt(0)) >>> 0, 17)
  const next = () => {
    hash = (hash * 1664525 + 1013904223) >>> 0
    return hash / 4294967296
  }
  return Array.from({ length: 42 }, () => ({
    left: `${Math.round(next() * 100)}%`,
    top: `${Math.round(next() * 100)}%`,
    size: 1 + Math.round(next() * 2),
    delay: Math.round(next() * 2200),
  }))
}

function MoonMark({ mining = false }: { mining?: boolean }) {
  return (
    <div className="moon">
      {MOON_CRATERS.map((crater, i) => <span className="crater" key={i} style={{ left: crater.left, top: crater.top, width: crater.size, height: crater.size }} />)}
      {mining && <span className="moon-rover">▰</span>}
    </div>
  )
}

export default function Mooneto() {
  const [thread, setThread] = useState<Array<{ q: string; a?: Answer; error?: string }>>([])
  const [latest, setLatest] = useState<Answer | null>(null)
  const [input, setInput] = useState("")
  const [busy, setBusy] = useState(false)
  const [showChat, setShowChat] = useState(false)
  const [showReport, setShowReport] = useState(false)
  const [activeQuestion, setActiveQuestion] = useState("")
  const [exploring, setExploring] = useState(false)
  const [reasoningMs, setReasoningMs] = useState(0)
  const [thinkingMs, setThinkingMs] = useState(0)
  const [starField, setStarField] = useState<FieldStar[]>(() => makeStarField("mooneto"))
  const bottom = useRef<HTMLDivElement>(null)
  const thinkingStarted = useRef(0)
  const miningScene = depictsMining(latest) || depictsMiningText(activeQuestion)

  function treatyPosition(index: number) {
    const star = starField[(index * 7 + 3) % starField.length]
    return { left: `${18 + parseFloat(star.left) * 0.64}%`, top: `${15 + parseFloat(star.top) * 0.7}%` }
  }

  useEffect(() => {
    if (!exploring) return
    const ticker = window.setInterval(() => setThinkingMs(Date.now() - thinkingStarted.current), 100)
    return () => window.clearInterval(ticker)
  }, [exploring])

  useEffect(() => {
    bottom.current?.scrollIntoView({ behavior: "smooth" })
  }, [thread, busy])

  async function submit(question: string) {
    if (!question.trim() || busy) return
    setBusy(true)
    setShowChat(false)
    setActiveQuestion(question.trim())
    setShowReport(false)
    setExploring(true)
    thinkingStarted.current = Date.now()
    setThinkingMs(0)
    setReasoningMs(0)
    setStarField(makeStarField(`${question}:${Date.now()}`))
    setLatest(null)
    setInput("")
    const turn = thread.length
    setThread((t) => [...t, { q: question }])

    try {
      // Cala answers questions in isolation, so follow-ups need the thread
      // rewritten into a standalone question server-side.
      const history = thread.flatMap((t) =>
        t.a ? [`Q: ${t.q}`, `A: ${t.a.verdict}`] : []
      )
      // The case file so far. A business-case memo has to be built from everything the
      // conversation established, not just from the last question.
      const answered = thread.flatMap((t) => (t.a ? [t.a] : []))
      const gathered = {
        countries: answered.flatMap((a) => a.countries),
        laws: [...new Set(answered.flatMap((a) => a.laws))],
      }
      const res = await fetch("/api/ask", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ question, history, gathered }),
      })
      const data = await res.json()
      if (!res.ok) throw new Error(data.error ?? "request failed")
      setReasoningMs(Date.now() - thinkingStarted.current)
      setExploring(false)
      setThread((t) => t.map((x, i) => (i === turn ? { ...x, a: data } : x)))
      setLatest(data)
    } catch (err: any) {
      setExploring(false)
      setThread((t) => t.map((x, i) => (i === turn ? { ...x, error: err.message } : x)))
    } finally {
      setBusy(false)
    }
  }

  return (
    <>
      <div className="stars" />
      <div className={`grid${busy ? " busy" : ""}`}>
        <section className={`chat${showChat ? " open" : ""}`}>
          <header>
            <div className="chat-heading">
              <h1>🌙 Mooneto</h1>
              <button className="chat-close" type="button" onClick={() => setShowChat(false)} aria-label="Close question panel">×</button>
            </div>
            <p>
              Space law, sourced. It tells you what is <em>settled</em>, what is{" "}
              <em>disputed</em>, and where it is written.
            </p>
          </header>

          <div className="thread">
            {thread.length === 0 && (
              <div className="hint">
                <p>Try asking</p>
                {SUGGESTIONS.map((s) => (
                  <button key={s} className="suggest" onClick={() => submit(s)}>
                    {s}
                  </button>
                ))}
              </div>
            )}

            {thread.map((turn, i) => (
              <div key={i}>
                <div className="q">{turn.q}</div>
                {turn.error && <div className="a err">⚠ {turn.error}</div>}
                {turn.a && (
                  <div className="a">
                    <p className="lead">{turn.a.verdict}</p>
                    {turn.a.resolved && turn.a.resolved !== turn.q && (
                      <p className="resolved">interpreted as: “{turn.a.resolved}”</p>
                    )}
                    {turn.a.plan && (
                      <div className="memo">
                        <h3>Recommended route</h3>
                        <ol>
                          {turn.a.plan.route.map((r, j) => (
                            <li key={j}>
                              {r.step}
                              <span className="basis">{r.basis}</span>
                            </li>
                          ))}
                        </ol>

                        <h3>Open risks</h3>
                        <ul className="risks">
                          {turn.a.plan.risks.map((r, j) => (
                            <li key={j}>
                              {r.risk}
                              <span className="basis">changes if: {r.trigger}</span>
                            </li>
                          ))}
                        </ul>

                        <h3>Legal confidence</h3>
                        <dl className="conf">
                          <dt>Ratification</dt>
                          <dd>{turn.a.plan.confidence.ratification}</dd>
                          <dt>National law</dt>
                          <dd>{turn.a.plan.confidence.nationalLaw}</dd>
                          <dt>Major-power dissent</dt>
                          <dd>{turn.a.plan.confidence.dissent}</dd>
                        </dl>
                      </div>
                    )}
                    {!turn.a.plan && turn.a.claims.map((c, j) => (
                      <div className="claim" key={j}>
                        <span className={`tag ${c.label}`}>{c.label}</span>
                        <p>{c.text}</p>
                        {c.why && <p className="why">{c.why}</p>}
                        {c.provision && (
                          <aside className="provision" aria-label="Legal provision">
                            <span className="provision-label">Legal provision</span>
                            <p className="provision-law">
                              {c.provision.law}
                              {c.provision.year ? ` · ${c.provision.year}` : ""}
                            </p>
                            <blockquote>{c.provision.text}</blockquote>
                          </aside>
                        )}
                      </div>
                    ))}
                  </div>
                )}
              </div>
            ))}
            {busy && <div className="a">Consulting treaties…</div>}
            <div ref={bottom} />
          </div>

          <form
            onSubmit={(e) => {
              e.preventDefault()
              submit(input)
            }}
          >
            <input
              value={input}
              onChange={(e) => setInput(e.target.value)}
              placeholder="Ask about doing business in space…"
            />
            <button type="submit" disabled={busy}>
              Ask
            </button>
          </form>
        </section>

        <section className="stage">
          {!showChat && <button className="chat-toggle" type="button" onClick={() => setShowChat(true)} aria-expanded={showChat}>
            <span>＋</span> Ask a question
          </button>}
          {showChat && <form className="ask-inline" onSubmit={(event) => { event.preventDefault(); submit(input) }}>
            <input autoFocus value={input} onChange={(event) => setInput(event.target.value)} placeholder="Ask about space law…" aria-label="Space law question" />
            <button type="submit" disabled={busy}>Ask</button>
            <button className="ask-cancel" type="button" onClick={() => setShowChat(false)} aria-label="Close question input">×</button>
          </form>}
          <div className="visual-stars" aria-hidden="true">
            {starField.map((star, i) => (
              <i key={i} style={{ left: star.left, top: star.top, width: star.size, height: star.size, animationDelay: `${star.delay}ms` }} />
            ))}
          </div>

          {(activeQuestion || latest) && (
            <div className="stage-header">
              <div className="question-cluster">
                <div className="stage-question">{activeQuestion || latest?.question}</div>
                {latest && (
                  <>
                    <button className="report-toggle" type="button" onClick={() => setShowReport((open) => !open)} aria-expanded={showReport}>
                      {showReport ? "Hide agent report" : "Open agent report"} <span>{showReport ? "↑" : "↓"}</span>
                    </button>
                    {showReport && (
                      <div className="agent-report">
                        <div className="report-counts"><span>{latest.laws.length} instruments</span><span>{latest.countries.length} jurisdictions</span></div>
                        {!latest.plan && latest.claims.slice(0, 6).map((claim, i) => (
                          <div className="report-line" key={i}><span className={`tag ${claim.label}`}>{claim.label}</span><span>{claim.text}</span></div>
                        ))}
                        {latest.plan && <p className="report-note">Decision memo assembled from the accumulated case file.</p>}
                      </div>
                    )}
                  </>
                )}
              </div>
              {latest && !exploring && <div className={`answer-card ${latest.tone}`}><span>agent answer</span><p>{latest.verdict}</p></div>}
            </div>
          )}

          {exploring && (
            <div className="exploration" aria-live="polite">
              <div className="exploration-orbit">
                <span className="orbit-ring" />
                {starField.slice(0, 12).map((star, i) => <span className="scout-star" key={i} style={{ left: star.left, top: star.top, animationDelay: `${star.delay}ms` }}>✦</span>)}
                <div className="exploration-moon"><MoonMark mining={miningScene} /></div>
                <span className="journey-rocket" style={{ animationDuration: "4.8s" }} aria-hidden="true">🚀</span>
              </div>
              <small>{(thinkingMs / 1000).toFixed(1)}s</small>
            </div>
          )}

          {!exploring && !latest && <div className="base-visual" aria-label="Space law knowledge base">
            <div className="base-orbit"><span className="base-core">SPACE<br />LAW</span>{["✦", "·", "✧", "·", "✦", "·"].map((mark, i) => <span className="base-star" key={i} style={{ animationDelay: `${i * 240}ms` }}>{mark}</span>)}</div>
            <p>Ask a question to navigate the legal constellation</p>
          </div>}

          {!exploring && latest && <div className="journey" aria-label="Agent journey through the legal instruments">
            <div className="journey-moon"><MoonMark mining={miningScene} /><span className="origin-label">the Moon</span></div>
            <div className="law-orbit">
              <span className="orbit-ring" />
              {latest.laws.map((law, i) => {
                const position = treatyPosition(i)
                return <div className="law-star" key={law} style={{ ...position, animationDelay: `${i * 180}ms` }}><span>✦</span><small>{law}</small></div>
              })}
              <span className="journey-rocket" style={{ animationDuration: `${Math.max(4, Math.min(12, reasoningMs / 1000))}s` }} aria-hidden="true">🚀</span>
            </div>
            <div className="return-label">route complete · evidence returned to the Moon</div>
          </div>}

          {!exploring && latest && latest.countries.length > 0 && <div className="jurisdictions" aria-label="Country positions found by the agent">
            <span className="jurisdictions-label">jurisdictions reached</span>
            <div className="flags">
              {latest.countries.map((c, i) => <div className={`flag ${c.stance}`} key={c.name} title={c.why} style={{ animationDelay: `${latest.laws.length * 180 + i * 70}ms` }}><span className="em">{flag(c.name)}</span><span>{c.name}</span><span className="st">{c.stance}</span></div>)}
            </div>
          </div>}
        </section>
      </div>
    </>
  )
:root{
  --bg:#05060d; --panel:#0c0f1c; --line:#1d2337;
  --ink:#e8ecf8; --dim:#8891ad;
  --settled:#31c48d; --disputed:#f5b53f; --unsupported:#6b7490;
  --rejects:#e8556d;
}
*{box-sizing:border-box;margin:0;padding:0}
html,body{height:100%}
body{
  background:var(--bg); color:var(--ink);
  font:15px/1.55 ui-sans-serif,-apple-system,"Segoe UI",Roboto,sans-serif;
  overflow:hidden;
}
.stars{
  position:fixed; inset:0; pointer-events:none; opacity:.5;
  background:
    radial-gradient(1.5px 1.5px at 20% 30%,#fff,transparent),
    radial-gradient(1.5px 1.5px at 70% 15%,#fff,transparent),
    radial-gradient(1px 1px at 45% 70%,#fff,transparent),
    radial-gradient(1.5px 1.5px at 85% 55%,#fff,transparent),
    radial-gradient(1px 1px at 10% 80%,#fff,transparent),
    radial-gradient(1px 1px at 60% 90%,#fff,transparent),
    radial-gradient(1.5px 1.5px at 35% 45%,#fff,transparent);
}
.grid{display:block; height:100vh; position:relative}

.chat{display:none}
.chat header{padding:22px 24px 16px; border-bottom:1px solid var(--line)}
.chat-heading{display:flex; align-items:center; justify-content:space-between}
.chat-close{width:30px; height:30px; border:1px solid var(--line); border-radius:50%; background:transparent;
  color:var(--dim); font-size:21px; line-height:1; cursor:pointer}.chat-close:hover{color:var(--ink); border-color:var(--ink)}
.chat h1{font-size:22px; letter-spacing:-.02em}
.chat header p{color:var(--dim); font-size:13px; margin-top:6px}
.chat header em{color:var(--ink); font-style:normal}
.thread{flex:1; overflow-y:auto; padding:18px 24px; display:flex;
        flex-direction:column; gap:18px; min-height:0}
.hint p{color:var(--dim); font-size:11px; text-transform:uppercase;
        letter-spacing:.09em; margin-bottom:10px}
.suggest{display:block; width:100%; text-align:left; margin-bottom:8px; cursor:pointer;
  background:transparent; border:1px solid var(--line); color:var(--dim);
  border-radius:9px; padding:10px 12px; font:inherit; font-size:13px}
.suggest:hover{border-color:var(--settled); color:var(--ink)}

.q{align-self:flex-start; background:#20304f; border-radius:12px 12px 12px 3px;
   padding:10px 14px; max-width:88%}
.a{border-left:2px solid var(--line); padding-left:14px}
.a .lead{font-size:16px; margin-bottom:14px; line-height:1.4}

.claim{padding:9px 0; border-top:1px solid var(--line)}
.claim:first-of-type{border-top:0}
.tag{display:inline-block; font-size:10px; letter-spacing:.1em; text-transform:uppercase;
     padding:2px 7px; border-radius:20px; margin-bottom:5px; font-weight:600}
.tag.settled{background:rgba(49,196,141,.14); color:var(--settled)}
.tag.disputed{background:rgba(245,181,63,.14); color:var(--disputed)}
.tag.unsupported{background:rgba(107,116,144,.16); color:var(--unsupported)}
.claim p{font-size:13.5px; color:#c9d1e6}
.claim .why{color:var(--dim); font-size:12px; font-style:italic; margin-top:3px}
.claim:has(.tag.unsupported){opacity:.72}
.provision{margin-top:9px; padding:9px 10px; border:1px solid var(--line); border-left:2px solid var(--settled);
  border-radius:0 7px 7px 0; background:#111527}
.provision-label{display:block; color:var(--dim); font-size:9px; letter-spacing:.1em; text-transform:uppercase;
  font-weight:600; margin-bottom:2px}
.provision-law{font-size:12px!important; color:var(--ink)!important; font-weight:600; margin:0 0 3px}
.provision blockquote{color:#c9d1e6; font-size:12px; line-height:1.45; margin:0; font-style:italic}
.err{color:var(--rejects); font-size:13px}

.chat-scrim{position:fixed; inset:0; z-index:15; border:0; background:rgba(0,0,0,.5); cursor:pointer}

form{display:flex; gap:9px; padding:16px 24px; border-top:1px solid var(--line)}
form input{flex:1; background:#111527; border:1px solid var(--line); color:var(--ink);
  border-radius:9px; padding:11px 13px; font:inherit}
form input:focus{outline:none; border-color:var(--settled)}
form button{background:var(--settled); color:#04120c; border:0; border-radius:9px;
  padding:0 18px; font:inherit; font-weight:600; cursor:pointer}
form button:disabled{opacity:.4; cursor:wait}

.stage{position:relative; width:100%; height:100vh; display:flex; flex-direction:column; align-items:center;
       justify-content:flex-start; gap:18px; padding:78px 40px 40px; overflow-y:auto}
.visual-stars{position:absolute; inset:0; overflow:hidden; pointer-events:none; z-index:0}
.visual-stars i{position:absolute; border-radius:50%; background:#fff; opacity:.28; animation:star-pulse 2.8s ease-in-out infinite alternate}
.visual-stars i:nth-child(3n){background:#ffe7a1; opacity:.42}.visual-stars i:nth-child(5n){opacity:.16}
.chat-toggle{position:absolute; z-index:3; top:20px; left:24px; border:1px solid var(--line); border-radius:20px;
  background:rgba(12,15,28,.86); color:var(--ink); padding:8px 14px; font:inherit; font-size:12px; cursor:pointer;
  box-shadow:0 8px 24px rgba(0,0,0,.22)}
.chat-toggle:hover{border-color:var(--settled); color:var(--settled)}
.chat-toggle span{font-size:16px; vertical-align:-1px; margin-right:4px}
.ask-inline{position:absolute; z-index:3; top:16px; left:24px; display:flex; align-items:center; gap:6px; width:min(390px,calc(100vw - 48px));
  padding:6px; border:1px solid var(--settled); border-radius:12px; background:rgba(12,15,28,.96); box-shadow:0 10px 35px rgba(0,0,0,.35)}
.ask-inline input{min-width:0; flex:1; border:0; outline:0; background:transparent; color:var(--ink); padding:7px 8px; font:inherit; font-size:13px}
.ask-inline>button[type="submit"]{border:0; border-radius:8px; background:var(--settled); color:#04120c; padding:7px 11px; font:inherit; font-size:12px; font-weight:600; cursor:pointer}
.ask-inline>button[type="submit"]:disabled{opacity:.4; cursor:wait}.ask-cancel{border:0; background:transparent; color:var(--dim); font-size:20px; line-height:1; padding:3px 5px; cursor:pointer}.ask-cancel:hover{color:var(--ink)}
.stage > :not(.visual-stars){z-index:1}
.stage-header{position:relative; z-index:2; width:100%; display:flex; align-items:flex-start;
  justify-content:space-between; gap:24px; flex:none}
.question-cluster{width:min(360px,42vw); margin-right:auto; pointer-events:auto}
.stage-question{display:inline-block; max-width:100%; padding:10px 14px; border-radius:12px 12px 12px 3px; background:#20304f;
  color:var(--ink); font-size:13px; line-height:1.35; box-shadow:0 9px 24px rgba(0,0,0,.22)}
.report-toggle{display:block; margin-top:7px; border:0; background:transparent; color:var(--dim); padding:0; font:inherit;
  font-size:10px; letter-spacing:.04em; cursor:pointer}.report-toggle:hover{color:var(--ink)}.report-toggle span{font-size:13px; margin-left:3px}
.agent-report{margin-top:8px; max-height:270px; overflow:auto; padding:11px 12px; border:1px solid var(--line); border-radius:9px;
  background:rgba(12,15,28,.94); box-shadow:0 12px 35px rgba(0,0,0,.3)}
.report-counts{display:flex; gap:10px; color:var(--dim); font-size:10px; text-transform:uppercase; letter-spacing:.07em; margin-bottom:8px}
.report-line{display:flex; align-items:flex-start; gap:7px; border-top:1px solid var(--line); padding:7px 0; color:#c9d1e6; font-size:11px; line-height:1.35}
.report-line .tag{flex:none; margin:0; font-size:8px}.report-note{color:var(--dim); font-size:11px; font-style:italic}
.answer-card{width:min(470px,45vw); margin-left:auto; padding:12px 16px 14px; border:1px solid var(--line); border-radius:12px 12px 3px 12px;
  background:rgba(12,15,28,.9); box-shadow:0 12px 35px rgba(0,0,0,.3); pointer-events:auto}
.answer-card > span{display:block; color:var(--dim); text-transform:uppercase; letter-spacing:.1em; font-size:9px; margin-bottom:4px}
.answer-card p{font-size:17px; line-height:1.35; font-weight:600}.answer-card.no p{color:var(--rejects)}.answer-card.split p{color:var(--disputed)}.answer-card.yes p{color:var(--settled)}
.exploration{width:min(690px,100%); min-height:300px; display:flex; flex-direction:column; align-items:center; justify-content:center; gap:5px;
  border:1px solid var(--line); border-radius:18px; background:rgba(5,6,13,.35); color:var(--dim)}
.exploration small{font-variant-numeric:tabular-nums; color:var(--dim)}
.exploration-orbit{width:min(620px,100%); height:280px; position:relative; border-radius:50%}
.exploration-moon{position:absolute; z-index:2; left:50%; top:50%; transform:translate(-50%,-50%)}.exploration-moon .moon{width:148px;height:148px}
.scout-star{position:absolute; z-index:3; color:#ffe7a1; font-size:23px; line-height:1; opacity:.2; animation:scout-glow 2.1s ease-in-out infinite alternate}
.base-visual{display:flex; flex-direction:column; align-items:center; gap:20px; margin:auto; color:var(--dim); text-align:center}
.base-visual p{font-size:12px; letter-spacing:.04em}.base-orbit{width:280px; height:280px; position:relative; display:grid; place-items:center; border:1px dashed #293149; border-radius:50%; box-shadow:0 0 100px rgba(80,100,180,.1)}
