item.stdout:
/** Cala client: turns a natural-language legal question into structured claims. */

const API = "https://api.cala.ai"

type Origin = { source?: { name?: string; url?: string }; document?: { name?: string; url?: string } }
type ContextEntry = { id: string; content: string; origins?: Origin[] }
type Explain = { content: string; references?: string[] }
type Entity = { id: string; name: string; entity_type: string }

export type Source = { name: string; url: string }
export type Claim = { text: string; sources: Source[] }
export type CalaResult = {
  question: string
  answer: string
  claims: Claim[]
  countries: string[]
  laws: string[]
}

function sourcesFor(byId: Map<string, ContextEntry>, refs: string[] = []): Source[] {
  const out: Source[] = []
  const seen = new Set<string>()
  for (const ref of refs) {
    for (const origin of byId.get(ref)?.origins ?? []) {
      const doc = origin.document ?? origin.source ?? {}
      if (doc.url && !seen.has(doc.url)) {
        seen.add(doc.url)
        out.push({ name: doc.name ?? doc.url, url: doc.url })
      }
    }
  }
  return out
}

export async function ask(question: string): Promise<CalaResult> {
  const key = process.env.CALA_API_KEY
  if (!key) throw new Error("CALA_API_KEY is not set")

  // Cala occasionally returns a transient 5xx. A live demo cannot afford that,
  // so retry server errors with a short backoff.
  let res: Response | null = null
  for (let attempt = 0; attempt < 3; attempt++) {
    res = await fetch(`${API}/v1/knowledge/search`, {
      method: "POST",
      headers: { "X-API-KEY": key, "Content-Type": "application/json" },
      body: JSON.stringify({ input: question }),
    })
    if (res.ok) break
    if (res.status < 500) throw new Error(`Cala returned ${res.status}`)
    console.warn(`[cala] ${res.status} on attempt ${attempt + 1}, retrying`)
    await new Promise((r) => setTimeout(r, 800 * (attempt + 1)))
  }
  if (!res || !res.ok) throw new Error(`Cala unavailable (${res?.status ?? "no response"})`)

  const raw = await res.json()
  const byId = new Map<string, ContextEntry>(
    (raw.context ?? []).map((c: ContextEntry) => [c.id, c])
  )
  const entities: Entity[] = raw.entities ?? []
  const namesOfType = (t: string) =>
    entities.filter((e) => e.entity_type === t).map((e) => e.name)

  return {
    question,
    answer: raw.content ?? "",
    claims: (raw.explainability ?? []).map((e: Explain) => ({
      text: e.content,
      sources: sourcesFor(byId, e.references),
    })),
    countries: namesOfType("Country"),
    laws: namesOfType("Law"),
  }
}

/**
 * Adversarial retrieval.
 *
 * A single query returns the framing of whoever wrote the sources, which for space
 * resources skews toward the states that permit it. A legal tool must not inherit that
 * bias, so we go looking for the opposing position explicitly and merge it in. This is
 * what turns an all-green answer into an honest split.
 */
export async function opposition(question: string): Promise<CalaResult | null> {
  try {
    return await ask(
      `Which states, treaties or legal scholars oppose or reject the following, and why? ${question}`
    )
  } catch (error) {
    console.warn("[cala] opposition lookup failed:", error)
    return null
  }
}
/** Labels each Cala claim as settled / disputed / unsupported and resolves country stances. */
import type { CalaResult, Claim } from "./cala"
import type { Provision } from "./laws"

const MODEL = process.env.OPENAI_MODEL ?? "gpt-4o-mini"

const SYSTEM = `You are a space-law analyst. You never invent law.

You are given a CORPUS of legal provisions — the articulated text of the treaties and
statutes in play. That corpus is the only authority you may rely on. Secondary commentary
is not authority, however plausible it sounds.

For each numbered claim, assign exactly one label:

- "settled": a provision in the corpus states it, and no other provision contradicts it.
- "disputed": provisions in the corpus point in different directions, OR a provision is
  silent or ambiguous on the point, OR the governing instrument lacks broad ratification.
- "unsupported": NO provision in the corpus establishes it. Use this whenever the claim
  rests only on commentary. This is not a failure — saying so is the product.

Set "provision" to the index of the corpus provision that carries the claim, or null when
the label is "unsupported". A claim labelled settled or disputed MUST cite a provision.

Also, for every country named in the material, give its stance on the specific
activity the user asked about:
  "enables" - its national law or signed position permits it
  "rejects" - it opposes that reading
  "unclear" - named but position not established by the material

Return ONLY JSON:
{"claims":[{"index":0,"label":"settled","provision":0,"why":"<max 12 words>"}],
 "countries":[{"name":"United States","stance":"enables","why":"<max 12 words>"}],
 "verdict":"<one sentence, plain language, answering the user's question>",
 "tone":"no|yes|split"}

"tone" describes the bottom line: "no" if the activity is prohibited, "yes" if clearly
permitted, "split" if it depends on jurisdiction or is unresolved.`

export type Label = "settled" | "disputed" | "unsupported"
export type Stance = "enables" | "rejects" | "unclear"

export type LabelledClaim = Claim & {
  label: Label
  why: string
  provision?: Provision | null
}
export type CountryStance = { name: string; stance: Stance; why: string }
export type Answer = {
  question: string
  verdict: string
  tone: "no" | "yes" | "split"
  claims: LabelledClaim[]
  countries: CountryStance[]
  laws: string[]
}

export async function analyse(found: CalaResult, corpus: Provision[] = []): Promise<Answer> {
  const key = process.env.OPENAI_API_KEY
  if (!key) throw new Error("OPENAI_API_KEY is not set")

  const numbered = found.claims.map((c, i) => `[${i}] ${c.text}`).join("\n")
  const provisions = corpus
    .map((p, i) => `[${i}] ${p.law}${p.year ? ` (${p.year})` : ""}: ${p.text}`)
    .join("\n")

  const res = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      model: MODEL,
      temperature: 0,
      response_format: { type: "json_object" },
      messages: [
        { role: "system", content: SYSTEM },
        {
          role: "user",
          content:
            `Question: ${found.question}\n\n` +
            `CORPUS of legal provisions (the only authority):\n${provisions || "(empty)"}\n\n` +
            `Claims to label:\n${numbered}\n\n` +
            `Countries named: ${found.countries.join(", ") || "none"}`,
        },
      ],
    }),
  })
  if (!res.ok) throw new Error(`OpenAI returned ${res.status}`)

  const body = await res.json()
  const verdict = JSON.parse(body.choices[0].message.content)

  const labels = new Map<number, { label: Label; why: string; provision?: number | null }>(
    (verdict.claims ?? []).map((c: any) => [
      c.index,
      { label: c.label, why: c.why, provision: c.provision },
    ])
  )

  return {
    question: found.question,
    verdict: verdict.verdict ?? "",
    tone: verdict.tone ?? "split",
    claims: found.claims.map((c, i) => {
      const verdictFor = labels.get(i)
      const cited =
        typeof verdictFor?.provision === "number" ? corpus[verdictFor.provision] : null
      // Enforced in code, not left to the prompt: no provision, no standing.
      const label: Label = cited ? verdictFor!.label : "unsupported"
      return { ...c, label, why: verdictFor?.why ?? "", provision: cited ?? null }
    }),
    countries: verdict.countries ?? [],
    laws: found.laws,
  }
}
/**
 * Turns a conversational follow-up into a self-contained question.
 *
 * Cala answers a question in isolation, so "but can I keep what I extract there?"
 * returns nothing — there is no "there". Rewriting against the conversation so far
 * is what lets the user actually have a conversation.
 */

const MODEL = process.env.OPENAI_MODEL ?? "gpt-4o-mini"

const SYSTEM = `Rewrite the user's latest question so it stands alone, resolving every
pronoun and reference against the conversation. Keep it in the user's language and
keep it short. Preserve the legal subject matter exactly — never broaden or narrow it.

If the question already stands alone, return it unchanged.

Return ONLY JSON: {"question":"<rewritten question>"}`

export async function standalone(question: string, history: string[]): Promise<string> {
  if (history.length === 0) return question

  const key = process.env.OPENAI_API_KEY
  if (!key) throw new Error("OPENAI_API_KEY is not set")

  const res = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      model: MODEL,
      temperature: 0,
      response_format: { type: "json_object" },
      messages: [
        { role: "system", content: SYSTEM },
        {
          role: "user",
          content: `Conversation so far:\n${history.join("\n")}\n\nLatest question: ${question}`,
        },
      ],
    }),
  })
  if (!res.ok) return question // never block the answer on the rewrite

  const body = await res.json()
  try {
    return JSON.parse(body.choices[0].message.content).question || question
  } catch {
    return question
  }
}
