/**
 * Turns a conversational follow-up into a self-contained question.
 *
 * Cala answers a question in isolation, so "but can I keep what I extract there?"
 * returns nothing — there is no "there". Rewriting against the conversation so far
 * is what lets the user actually have a conversation.
 */

const MODEL = process.env.OPENAI_MODEL ?? "gpt-4o-mini"

const SYSTEM = `Rewrite the user's latest question so it stands alone, resolving every
pronoun and reference against the conversation. Keep it in the user's language and
keep it short. Preserve the legal subject matter exactly — never broaden or narrow it.

If the question already stands alone, return it unchanged.

Return ONLY JSON: {"question":"<rewritten question>"}`

/** Keep common Moon phrasing stable so equivalent questions share retrieval/cache paths. */
export function canonicalizeSpaceTerms(question: string): string {
  return question.replace(/\b(?:in|on)\s+(?:the\s+)?moon\b/gi, "on the Moon")
}

export async function standalone(question: string, history: string[]): Promise<string> {
  if (history.length === 0) return question

  const key = process.env.OPENAI_API_KEY
  if (!key) throw new Error("OPENAI_API_KEY is not set")

  const res = await fetch("https://api.openai.com/v1/chat/completions", {
    method: "POST",
    headers: { Authorization: `Bearer ${key}`, "Content-Type": "application/json" },
    body: JSON.stringify({
      model: MODEL,
      temperature: 0,
      response_format: { type: "json_object" },
      messages: [
        { role: "system", content: SYSTEM },
        {
          role: "user",
          content: `Conversation so far:\n${history.join("\n")}\n\nLatest question: ${question}`,
        },
      ],
    }),
  })
  if (!res.ok) return question // never block the answer on the rewrite

  const body = await res.json()
  try {
    return JSON.parse(body.choices[0].message.content).question || question
  } catch {
    return question
  }
}
import { NextResponse } from "next/server"
import { ask, opposition } from "@/lib/mooneto/cala"
import { analyse, type Answer } from "@/lib/mooneto/classify"
import { canonicalizeSpaceTerms, standalone } from "@/lib/mooneto/rewrite"
import { read, write } from "@/lib/mooneto/cache"
import { buildPlan, wantsPlan } from "@/lib/mooneto/plan"
import { CORE, corpus } from "@/lib/mooneto/laws"

export const runtime = "nodejs"
export const maxDuration = 120

export async function POST(request: Request) {
  const started = Date.now()
  try {
    const { question, history = [], gathered = null } = await request.json()
    if (!question?.trim()) {
      return NextResponse.json({ error: "question is required" }, { status: 400 })
    }

    const asked = question.trim()
    const canonical = canonicalizeSpaceTerms(asked)

    // Check the cache before the rewrite: the rewrite itself costs a model call.
    const cached = await read<Answer>(canonical, history)
    if (cached) {
      console.log(`[mooneto] cache hit (${Date.now() - started}ms)`)
      return NextResponse.json({ ...cached, asked, cached: true })
    }

    const resolved = await standalone(canonical, history)
    if (resolved !== asked) console.log(`[mooneto] rewrote -> ${resolved}`)

    // Ask the question, and in parallel ask who disagrees. Merging both keeps a
    // one-sided source set from producing a falsely settled answer.
    const [found, against] = await Promise.all([ask(resolved), opposition(resolved)])
    if (against) {
      found.claims.push(...against.claims)
      found.countries = [...new Set([...found.countries, ...against.countries])]
      found.laws = [...new Set([...found.laws, ...against.laws])]
    }

    // The legal corpus: the articulated provisions of every instrument Cala named.
    // Claims are judged against this and nothing else.
    // Cala can return useful claims without tagging a Law entity (especially for
    // colloquial mining questions). Keep the legal constellation visible and give
    // the classifier the committed baseline rather than presenting zero instruments.
    const laws = found.laws.length > 0 ? found.laws : CORE
    const legalFound = { ...found, laws }
    const provisions = await corpus(laws)
    console.log(`[mooneto] corpus: ${provisions.length} provision(s) from ${laws.length} law(s)`)

    const analysed = await analyse(legalFound, provisions)
    // A request for a decision gets a memo, not a claim list.
    // Fold in everything established earlier in the thread, so the memo reasons over the
    // whole case file rather than only the last question's findings.
    const caseFile = gathered
      ? {
          ...analysed,
          laws: [...new Set([...analysed.laws, ...(gathered.laws ?? [])])],
          countries: [
            ...analysed.countries,
            ...(gathered.countries ?? []).filter(
              (c: any) => !analysed.countries.some((k) => k.name === c.name)
            ),
          ],
        }
      : analysed
    const plan = wantsPlan(asked) ? await buildPlan(asked, caseFile) : null
    const answer = { ...analysed, resolved, ...(plan ? { plan, verdict: plan.verdict } : {}) }
    await write(asked, history, answer)
    console.log(`[mooneto] fresh (${Date.now() - started}ms)`)
    return NextResponse.json({ ...answer, asked, resolved, cached: false })
  } catch (error: any) {
    console.error("[mooneto]", error)
    return NextResponse.json({ error: error.message ?? "failed" }, { status: 500 })
  }
}

