.exploration-caption{display:flex; align-items:center; gap:8px; color:#b4bed7; font-size:12px; letter-spacing:.02em}
.exploration-caption time{margin-left:3px; color:var(--dim); font-variant-numeric:tabular-nums}
.live-dot{width:7px; height:7px; border-radius:50%; background:var(--settled); box-shadow:0 0 0 4px rgba(49,196,141,.12); animation:live-pulse 1.8s ease-in-out infinite}
.base-visual{margin:auto; gap:24px; max-width:620px; padding:24px 0}
.base-orbit{width:clamp(230px,28vw,300px); height:clamp(230px,28vw,300px)}
.base-copy{display:flex; flex-direction:column; align-items:center; gap:5px}
.base-title{color:#c9d1e6; font-size:15px; letter-spacing:.02em}
.base-hint{color:var(--dim); font-size:12px; text-align:center}
.base-suggestions{display:flex; flex-wrap:wrap; justify-content:center; gap:8px; margin-top:12px}
.base-suggestions button{border:1px solid #293149; border-radius:999px; background:rgba(12,15,28,.68); color:#aeb8d0; padding:8px 12px; font:inherit; font-size:11px; line-height:1.25; cursor:pointer; transition:border-color .2s ease,color .2s ease,background .2s ease,transform .2s ease}
.base-suggestions button:hover{border-color:var(--settled); color:var(--ink); background:rgba(49,196,141,.08); transform:translateY(-1px)}
.journey{max-width:980px; min-height:clamp(400px,55vh,560px)}
.law-orbit{width:min(820px,100%); height:clamp(320px,42vh,430px)}
.journey-rocket{display:grid; place-items:center; width:34px; height:34px}
.journey-rocket .rocket-mark{display:block; width:30px; height:30px; color:#f5b53f; transform:rotate(45deg); filter:drop-shadow(0 0 8px rgba(245,181,63,.55))}
.journey-rocket{animation:none; transform:translate(-50%,-50%); transition:left .88s cubic-bezier(.22,.8,.24,1),top .88s cubic-bezier(.22,.8,.24,1)}
.journey-path{position:absolute; z-index:1; inset:0; width:100%; height:100%; overflow:visible; pointer-events:none; opacity:.5}
.journey-path path{fill:none; stroke:rgba(245,181,63,.42); stroke-width:.45; stroke-dasharray:1.6 2.4; vector-effect:non-scaling-stroke; stroke-linecap:round}
.law-star{opacity:.25; animation:none; transition:opacity .35s ease,filter .35s ease}
.law-star.visited{opacity:1; animation:law-arrive .55s ease both}
.return-label{bottom:0; color:#a3aec8}
.moon-rover{left:42%; bottom:22%; width:28px; height:14px; color:#f5b53f; font-size:0; animation:rover-cross 4s ease-in-out infinite}
.moon-rover::before{content:""; position:absolute; left:12px; top:-8px; width:2px; height:8px; background:#f5b53f; transform:rotate(16deg); transform-origin:bottom}
.moon-rover::after{content:""; position:absolute; right:-5px; top:3px; width:8px; height:5px; border:2px solid #f5b53f; border-left:0; transform:rotate(-22deg); transform-origin:left center}
.moon-rover i{position:absolute; bottom:-4px; width:8px; height:8px; border-radius:50%; background:#252b3c; border:2px solid #aeb5c5}
.moon-rover i:first-child{left:2px}.moon-rover i:nth-child(2){right:2px}
.moon-rover b{position:absolute; inset:2px 5px 3px; border-radius:3px; background:#f5b53f}
.jurisdictions{width:min(820px,100%); margin-top:-2px; padding-top:15px}
.flags{gap:8px}
.flag{padding:9px 13px; border-radius:12px; min-height:50px}
.flag .em{font-size:25px}

@keyframes live-pulse{0%,100%{opacity:.65; transform:scale(.9)}50%{opacity:1; transform:scale(1.08)}}

@media (max-width:760px){
  .stage{padding:76px 16px 30px; gap:18px}
  .stage-header{width:100%; flex-direction:column; gap:14px}
  .question-cluster,.answer-card{width:min(100%,560px); margin:0}
  .answer-card{align-self:flex-end; width:min(100%,480px)}
  .stage-question{font-size:13px}
  .exploration{min-height:320px; border-radius:15px}
