  .base-orbit{width:210px;height:210px}.base-core{font-size:16px}
  .base-suggestions button{width:100%; max-width:330px}
  .exploration{padding-inline:8px}.exploration-caption{font-size:11px}
  .exploration-video{border-radius:9px}
  .journey{min-height:340px}.law-orbit{height:270px}
  .journey-moon .moon{width:135px;height:135px}
  .jurisdictions{padding-top:11px}.flag{width:100%;justify-content:flex-start}
}
