+.answer-meta{display:flex; align-items:center; justify-content:space-between; gap:12px; margin-bottom:7px}
+.answer-meta span{color:var(--dim); text-transform:uppercase; letter-spacing:.12em; font-size:10px}
+.answer-meta strong{font-size:10px; font-weight:600; letter-spacing:.06em; text-transform:uppercase; color:#aeb8d0}
+.answer-card.no .answer-meta strong{color:var(--rejects)}.answer-card.split .answer-meta strong{color:var(--disputed)}.answer-card.yes .answer-meta strong{color:var(--settled)}
+.answer-details{width:min(1120px,100%); display:grid; grid-template-columns:minmax(0,1.18fr) minmax(320px,.82fr); gap:14px; margin-top:2px; padding-bottom:22px}
+.evidence-panel,.answer-details .jurisdictions{min-width:0; border:1px solid var(--line); border-radius:16px; background:rgba(12,15,28,.78); padding:18px 20px; box-shadow:0 16px 45px rgba(0,0,0,.2)}
+.panel-heading{display:flex; align-items:flex-start; justify-content:space-between; gap:16px; padding-bottom:14px; border-bottom:1px solid var(--line)}
+.panel-heading h2{color:#e0e6f4; font-size:15px; line-height:1.2; letter-spacing:-.01em}
+.panel-heading p{margin-top:4px; color:var(--dim); font-size:11px; line-height:1.35}
+.panel-count{flex:none; color:var(--dim); font-size:10px; text-transform:uppercase; letter-spacing:.08em; white-space:nowrap}
+.treaty-list{display:flex; flex-direction:column}
+.treaty-row{padding:14px 0 13px; border-bottom:1px solid var(--line)}
+.treaty-row:last-child{border-bottom:0; padding-bottom:1px}
+.treaty-row-head{display:flex; align-items:flex-start; gap:10px; min-width:0}
+.treaty-mark{flex:none; margin-top:1px; color:#ffe7a1; font-size:20px; line-height:1; text-shadow:0 0 12px rgba(245,181,63,.5)}
+.treaty-name{min-width:0; flex:1}.treaty-name h3{color:#e0e6f4; font-size:13px; line-height:1.25; font-weight:600; overflow-wrap:anywhere}.treaty-name p{margin-top:3px; color:var(--dim); font-size:10px; line-height:1.3}
+.evidence-status{flex:none; border-radius:999px; padding:4px 7px; font-size:9px; text-transform:uppercase; letter-spacing:.06em; line-height:1.15}
+.evidence-status.grounded{color:var(--settled); background:rgba(49,196,141,.11)}
+.evidence-status.ungrounded{color:var(--unsupported); background:rgba(107,116,144,.12)}
+.treaty-row blockquote{margin:9px 0 0 30px; color:#c9d1e6; font-size:12px; line-height:1.45; border-left:1px solid rgba(245,181,63,.45); padding-left:10px}
+.evidence-empty{margin-top:13px; color:var(--dim); font-size:11px; line-height:1.45}
+.answer-details .jurisdictions{margin:0; padding-top:18px}
+.answer-details .jurisdictions .panel-heading{margin-bottom:0}
+.stance-counts{display:flex; flex-wrap:wrap; justify-content:flex-end; gap:5px 10px; max-width:220px}
+.stance-count{display:inline-flex; align-items:baseline; gap:4px; color:var(--dim); font-size:9px; text-transform:uppercase; letter-spacing:.05em; white-space:nowrap}
+.stance-count b{font-size:16px; line-height:1; font-weight:650}.stance-count.enables b{color:var(--settled)}.stance-count.rejects b{color:var(--rejects)}.stance-count.unclear b{color:var(--unsupported)}
+.answer-details .flags{display:grid; grid-template-columns:1fr; gap:8px; margin-top:14px}
+.answer-details .flag{display:block; min-width:0; min-height:0; padding:11px 12px; border-radius:11px; background:rgba(17,21,39,.74); animation:rise .45s ease backwards}
+.answer-details .flag-top{display:flex; align-items:center; gap:10px}
+.answer-details .flag h3{font-size:12px; line-height:1.2; font-weight:600; color:#e0e6f4}
+.answer-details .flag .em{display:block; flex:none; font-size:25px; line-height:1}
+.answer-details .flag .st{display:flex; align-items:center; gap:5px; margin-top:4px; font-size:9px; line-height:1; letter-spacing:.08em}
+.answer-details .flag p{margin-top:8px; padding-top:8px; border-top:1px solid rgba(29,35,55,.9); color:#aeb8d0; font-size:11px; line-height:1.4}
+.stance-mark{display:inline-block; width:6px; height:6px; border-radius:50%; background:currentColor; box-shadow:0 0 0 3px color-mix(in srgb,currentColor 13%,transparent)}
+.jurisdiction-empty{display:flex; align-items:center; gap:10px; margin-top:16px; padding:14px; border:1px dashed #293149; border-radius:10px; color:var(--dim); font-size:11px; line-height:1.4}
+.empty-orbit{display:grid; place-items:center; width:25px; height:25px; flex:none; border:1px dashed #46506d; border-radius:50%; color:#aeb8d0; font-size:18px; line-height:1}
+
+@media (max-width:900px){
+  .answer-details{grid-template-columns:1fr}
+  .answer-details .flags{grid-template-columns:repeat(2,minmax(0,1fr))}
+}
+@media (max-width:560px){
+  .evidence-panel,.answer-details .jurisdictions{padding:15px 14px; border-radius:13px}
+  .panel-heading{flex-direction:column; gap:8px}.panel-count{align-self:flex-start}
+  .stance-counts{justify-content:flex-start; max-width:none}
+  .answer-details .flags{grid-template-columns:1fr}
+  .treaty-row blockquote{margin-left:0; font-size:11px}
+  .evidence-status{font-size:8px}
+}
*** End Patch";
text(await tools.apply_patch(patch));

